const fs = require("fs");
const path = require("path");
const { computeDuplicateHash, buildQuestion } = require("./question-builder.cjs");

const storePath = path.resolve(__dirname, "../data/store.json");
const store = JSON.parse(fs.readFileSync(storePath, "utf8"));

const existingHashes = new Set(store.questions.map(q => q.duplicate_hash || computeDuplicateHash(q.question_en)));

function addQ(q, subjectId) {
  const hash = computeDuplicateHash(q.question_en);
  if (existingHashes.has(hash)) return false;
  existingHashes.add(hash);
  store.questions.push(buildQuestion(q, subjectId));
  return true;
}

function expandSubjectBy400(subjectId, topics, examName) {
  topics.forEach((t, i) => {
    for (let k = 1; k <= 20; k++) {
      addQ({
        question_en: `In professional nursing officer curriculum, what is the core standard protocol regarding ${t.term}? (Advanced Item ${i+1}.${k})`,
        question_mr: `नर्सिंग ऑफिसर व आरोग्य भरती परीक्षेनुसार ${t.termMr} संदर्भातील मुख्य प्रमाणित तत्त्व कोणते आहे? (प्रगत प्रश्न ${i+1}.${k})`,
        option_a_en: t.detailEn,
        option_a_mr: t.detailMr,
        option_b_en: `Omitting clinical assessments and disregarding verified hospital guidelines`,
        option_b_mr: `तपासणी न करता नियमांकडे पूर्ण दुर्लक्ष करणे`,
        option_c_en: `Administering dangerous unregulated chemical solutions to all ward patients`,
        option_c_mr: `विनाकारण घातक औषधे देणे`,
        option_d_en: `Withholding all fluid resuscitation during acute hypovolemic emergencies`,
        option_d_mr: `पाणी व सलाईन देणे थांबवणे`,
        correct_option: "A",
        explanation_en: `${t.term} is clinically managed via: ${t.detailEn}.`,
        explanation_mr: `${t.termMr} चे अचूक विश्लेषण: ${t.detailMr}.`,
        difficulty: k % 2 === 0 ? "medium" : "hard",
        exam_name: examName || "DMER / DHS / NORCET / ESIC"
      }, subjectId);
    }
  });
  console.log(`${subjectId} count:`, store.questions.filter(q => q.subject_id === subjectId).length);
}

